import csv, io, json, os, sys
from datetime import datetime, timezone, timedelta


def read_exports(d):
    rows = []
    ed = os.path.join(d, "exports")
    for name in sorted(os.listdir(ed)):
        p = os.path.join(ed, name)
        if not name.endswith(".csv") or not os.path.isfile(p):
            continue
        with open(p, "rb") as f:
            text = f.read().decode("utf-8")
        if text.startswith("\ufeff"):
            text = text[1:]
        first = text.replace("\r\n", "\n").split("\n", 1)[0]
        delim = next((c for c in (",", ";", "\t") if c in first), ",")
        for rec in _rows(text, delim):
            rows.append(rec)
    return rows


def _rows(text, delim):
    rd = csv.reader(io.StringIO(text, newline=""), delimiter=delim, quotechar='"')
    header = None
    for cells in rd:
        if header is None:
            header = [c.strip() for c in cells]
            continue
        cells = [c.strip() for c in cells]
        if not any(cells):
            continue
        rec = {}
        for i, h in enumerate(header):
            v = cells[i] if i < len(cells) else ""
            rec[h] = v if v != "" else None
        yield rec


def parse_time(s, meta):
    if meta.get("submitted_format") == "local":
        sign = 1 if meta["utc_offset"][0] == "+" else -1
        hh, mm = meta["utc_offset"][1:].split(":")
        tz = timezone(sign * timedelta(hours=int(hh), minutes=int(mm)))
        return datetime.strptime(s, "%Y-%m-%d %H:%M:%S").replace(tzinfo=tz)
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def parse_dur(s, fmt):
    if fmt == "clock":
        t = 0
        for p in s.split(":"):
            t = t * 60 + int(p)
        return t
    return int(s)


def to_int(v):
    try:
        return int(v)
    except ValueError:
        return int(float(v))


def recode_val(entry, v):
    rc = entry.get("recode")
    if rc is not None:
        return to_int(rc[v]) if not isinstance(rc[v], int) else rc[v]
    return to_int(v)


def read_answer(q, entry, row, cb):
    t = q["type"]
    missing = {o["code"] for o in q.get("options", []) if o.get("missing")}
    excl = {o["code"] for o in q.get("options", []) if o.get("exclusive")}
    if t == "single":
        v = row.get(entry["column"])
        if v is None:
            return None
        c = recode_val(entry, v)
        return None if c in missing else c
    if t == "multi":
        chosen = set()
        if "columns" in entry:
            for code, col in entry["columns"].items():
                if row.get(col) == "1":
                    chosen.add(int(code))
        else:
            v = row.get(entry["column"])
            if v is not None:
                for el in v.split(entry["separator"]):
                    el = el.strip()
                    if el:
                        chosen.add(recode_val(entry, el))
        if chosen & excl and chosen - excl:
            chosen -= excl
        elif chosen and chosen <= excl and len(chosen) >= 1 and (chosen & excl):
            # only exclusive options
            if len(chosen) >= 2:
                chosen = set()
        chosen -= missing
        return frozenset(chosen) if chosen else None
    if t == "age":
        v = row.get(entry["column"])
        if v is None:
            return None
        src = entry.get("source")
        if src == "band":
            return recode_val(entry, v)
        age = to_int(v)
        if src == "birth_year":
            age = int(cb["reference_date"][:4]) - age
        for b in q["bands"]:
            if b["min"] <= age <= b["max"]:
                return b["code"]
        return None


def median2(vals):  # twice the median
    vals = sorted(vals)
    n = len(vals)
    return 2 * vals[n // 2] if n % 2 else vals[n // 2 - 1] + vals[n // 2]


def r2(x):
    return None if x is None else round(x + 0.0, 2)


def main(inp, outp):
    def load(n):
        with open(os.path.join(inp, n), encoding="utf-8") as f:
            return json.load(f)
    cb, wt, plan = load("codebook.json"), load("weighting.json"), load("tables.json")
    vkeys = list(cb["versions"])
    allrows = []
    for r in read_exports(inp):
        v = r.get("form_version")
        meta = cb["versions"][v]["meta"]
        rid = r.get(meta["id"])
        complete = r.get(meta["status"]) == meta["complete"]
        sub = r.get(meta["submitted"])
        t = parse_time(sub, meta) if sub else datetime.min.replace(tzinfo=timezone.utc)
        lp = r.get(meta["last_page"])
        lp = to_int(lp) if lp is not None else 0
        du = r.get(meta["duration"])
        du = parse_dur(du, meta["duration_format"]) if du is not None else 0
        allrows.append(dict(v=v, id=rid, complete=complete, t=t, lp=lp, dur=du, raw=r))
    stats = {v: dict(rows=0, duplicates=0, short_partials=0, speeders=0, complete=0, partial=0) for v in vkeys}
    byid = {}
    for r in allrows:
        stats[r["v"]]["rows"] += 1
        byid.setdefault(r["id"], []).append(r)
    kept = []
    for rid, rs in byid.items():
        best = rs[0]
        for r in rs[1:]:
            if (r["complete"], r["t"]) > (best["complete"], best["t"]):
                best = r
        for r in rs:
            if r is not best:
                stats[r["v"]]["duplicates"] += 1
        kept.append(best)
    k2 = []
    for r in kept:
        if not r["complete"] and r["lp"] < cb["partial_min_page"]:
            stats[r["v"]]["short_partials"] += 1
        else:
            k2.append(r)
    med = {}
    for v in vkeys:
        ds = [r["dur"] for r in k2 if r["v"] == v and r["complete"]]
        med[v] = median2(ds) if ds else None
    final = []
    for r in k2:
        if r["complete"] and r["dur"] * 10 < med[r["v"]] * 2 * 2 // 2 * 1 and r["dur"] * 10 < med[r["v"]] * 4:
            stats[r["v"]]["speeders"] += 1
        else:
            final.append(r)
    for r in final:
        stats[r["v"]]["complete" if r["complete"] else "partial"] += 1
    # answers
    qs = {q["id"]: q for q in cb["questions"]}
    for r in final:
        asked, ans = {}, {}
        for q in cb["questions"]:
            e = q["versions"].get(r["v"])
            ok = e is not None and (r["complete"] or e["page"] <= r["lp"])
            if ok and q.get("ask_if"):
                a = q["ask_if"]
                pa = ans.get(a["question"])
                if not asked.get(a["question"]) or pa is None:
                    ok = False
                elif isinstance(pa, frozenset):
                    ok = bool(pa & set(a["codes"]))
                else:
                    ok = pa in a["codes"]
            asked[q["id"]] = ok
            ans[q["id"]] = read_answer(q, e, r["raw"], cb) if ok else None
        r["ans"] = ans
    n = len(final)
    w = [1.0] * n
    dims = []
    for d in wt["dimensions"]:
        qid = d["question"]
        present = {r["ans"][qid] for r in final if r["ans"][qid] is not None}
        tg = {int(k): float(v) for k, v in d["targets"].items() if int(k) in present}
        s = sum(tg.values())
        if not tg or s <= 0:
            continue
        cats = {}
        for i, r in enumerate(final):
            a = r["ans"][qid]
            if a in tg:
                cats.setdefault(a, []).append(i)
        dims.append(({c: v / s for c, v in tg.items()}, cats))
    for _ in range(wt.get("max_iterations", 100)):
        done = True
        for shares, cats in dims:
            T = sum(w[i] for idx in cats.values() for i in idx)
            fs = {}
            for c, idx in cats.items():
                Wc = sum(w[i] for i in idx)
                fs[c] = shares[c] * T / Wc
            for c, idx in cats.items():
                for i in idx:
                    w[i] *= fs[c]
                if abs(fs[c] - 1) > wt.get("tolerance", 1e-10):
                    done = False
        if done:
            break
    if n:
        m = sum(w) / n
        hi, lo = wt["cap"] * m, wt["floor"] * m
        w = [min(max(x, lo), hi) for x in w]
        m2 = sum(w) / n
        w = [x / m2 for x in w]
    summary = {"versions": [dict(version=v, **stats[v]) for v in vkeys], "respondents": n,
               "effective_n": r2(sum(w) ** 2 / sum(x * x for x in w)) if n else None,
               "weight_min": r2(min(w)) if n else None, "weight_max": r2(max(w)) if n else None}
    # columns
    cols = [("total", list(range(n)))]
    for bq in plan["banner"]:
        q = qs[bq]
        codes = [b["code"] for b in q["bands"]] if q["type"] == "age" else [o["code"] for o in q["options"] if not o.get("missing")]
        for c in codes:
            cols.append((f"{bq}:{c}", [i for i, r in enumerate(final) if r["ans"][bq] == c]))
    tables = []
    for t in plan["tables"]:
        q = qs[t["question"]]
        opts = [o for o in q["options"] if not o.get("missing")]
        multi = q["type"] == "multi"
        has = lambda a, codes: (bool(a & set(codes)) if multi else a in codes)
        out = []
        for cid, members in cols:
            idx = [i for i in members if final[i]["ans"][t["question"]] is not None]
            wb = sum(w[i] for i in idx)
            vals = {}
            keys = [str(o["code"]) for o in opts] + [x["id"] for x in t.get("nets", [])] + (["mean"] if t.get("mean") else [])
            if not idx:
                vals = {k: None for k in keys}
                out.append({"column": cid, "base": 0, "weighted_base": 0, "values": vals})
                continue
            A = {i: final[i]["ans"][t["question"]] for i in idx}
            for o in opts:
                vals[str(o["code"])] = r2(100 * sum(w[i] for i in idx if has(A[i], [o["code"]])) / wb)
            for x in t.get("nets", []):
                vals[x["id"]] = r2(100 * sum(w[i] for i in idx if has(A[i], x["codes"])) / wb)
            if t.get("mean"):
                sc = {o["code"]: o["score"] for o in opts}
                vals["mean"] = r2(sum(w[i] * sc[A[i]] for i in idx) / wb)
            out.append({"column": cid, "base": len(idx), "weighted_base": r2(wb), "values": vals})
        tables.append({"table": t["id"], "columns": out})
    with open(outp, "w", encoding="utf-8") as f:
        json.dump({"survey": cb["survey"], "summary": summary, "tables": tables}, f, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
